package lk.dexlanka.erp;

import java.util.*;
import org.springframework.stereotype.Service;

@Service
@org.springframework.transaction.annotation.Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
class Queries {
    final Store s; Queries(Store s){this.s=s;}
    Map<String,Object> state(Actor a,int days) {
        Store.require(Set.of(7,14,30,90).contains(days),"Choose a supported reporting period");
        var t=a.tenant();var data=new LinkedHashMap<String,Object>();
        boolean financial=Set.of("ADMIN","PLANNER").contains(a.role());
        data.put("company",s.one("SELECT id,name,currency,demo FROM tenants WHERE id=?",t));
        if(a.role().equals("ADMIN")) data.put("users",s.list("SELECT id,email,name,role,active FROM users WHERE tenant_id=? ORDER BY name LIMIT 250",t));
        data.put("factories",s.list("SELECT * FROM factories WHERE tenant_id=? ORDER BY name",t));
        data.put("warehouses",s.list("SELECT * FROM warehouses WHERE tenant_id=? ORDER BY name",t));
        data.put("partners",s.list("SELECT * FROM partners WHERE tenant_id=? ORDER BY name LIMIT 250",t));
        data.put("machines",s.list("SELECT m.*,COALESCE((SELECT SUM(o.good_qty) FROM manufacturing_orders o WHERE o.tenant_id=m.tenant_id AND o.machine_id=m.id),0) AS output FROM machines m WHERE m.tenant_id=? ORDER BY code",t));
        data.put("items",s.list("SELECT i.*,COALESCE(SUM(b.quantity),0) AS on_hand,COALESCE(SUM(b.reserved),0) AS reserved,COALESCE(SUM(CASE WHEN l.status='RELEASED' THEN b.quantity-b.reserved ELSE 0 END),0) AS available,COALESCE(SUM(b.value_amount),0) AS stock_value FROM items i LEFT JOIN lots l ON l.tenant_id=i.tenant_id AND l.item_id=i.id LEFT JOIN stock_balances b ON b.tenant_id=l.tenant_id AND b.lot_id=l.id WHERE i.tenant_id=? GROUP BY i.id ORDER BY i.sku LIMIT 250",t));
        data.put("orders",s.list("SELECT o.*,i.name AS product,i.sku,i.uom,m.code AS machine,p.name AS customer FROM manufacturing_orders o JOIN items i ON i.tenant_id=o.tenant_id AND i.id=o.product_id JOIN machines m ON m.tenant_id=o.tenant_id AND m.id=o.machine_id LEFT JOIN sales_orders so ON so.tenant_id=o.tenant_id AND so.id=o.sales_order_id LEFT JOIN partners p ON p.tenant_id=so.tenant_id AND p.id=so.customer_id WHERE o.tenant_id=? ORDER BY o.created_at DESC,o.number LIMIT 250",t));
        data.put("boms",s.list("SELECT b.*,i.name AS product,i.sku,(SELECT COALESCE(SUM(bl.quantity*mi.standard_cost),0) FROM bom_lines bl JOIN items mi ON mi.tenant_id=bl.tenant_id AND mi.id=bl.item_id WHERE bl.tenant_id=b.tenant_id AND bl.bom_id=b.id)/b.output_qty/b.yield_factor AS unit_cost FROM boms b JOIN items i ON i.tenant_id=b.tenant_id AND i.id=b.product_id WHERE b.tenant_id=? ORDER BY i.name,b.revision DESC LIMIT 250",t));
        data.put("bomLines",s.list("SELECT l.*,i.name,i.sku,i.uom,i.standard_cost FROM bom_lines l JOIN items i ON i.tenant_id=l.tenant_id AND i.id=l.item_id WHERE l.tenant_id=? ORDER BY l.bom_id,i.name LIMIT 1000",t));
        data.put("sales",s.list("SELECT so.*,p.name AS customer,i.name AS product,i.uom FROM sales_orders so JOIN partners p ON p.tenant_id=so.tenant_id AND p.id=so.customer_id JOIN items i ON i.tenant_id=so.tenant_id AND i.id=so.product_id WHERE so.tenant_id=? ORDER BY so.due_date LIMIT 250",t));
        data.put("purchases",s.list("SELECT po.*,p.name AS supplier,i.name AS item,i.uom FROM purchase_orders po JOIN partners p ON p.tenant_id=po.tenant_id AND p.id=po.supplier_id JOIN items i ON i.tenant_id=po.tenant_id AND i.id=po.item_id WHERE po.tenant_id=? ORDER BY po.created_at DESC LIMIT 250",t));
        data.put("lots",s.list("SELECT l.*,i.name AS item,i.sku,i.uom,b.quantity,b.reserved,b.value_amount,w.name AS warehouse FROM lots l JOIN items i ON i.tenant_id=l.tenant_id AND i.id=l.item_id JOIN stock_balances b ON b.tenant_id=l.tenant_id AND b.lot_id=l.id JOIN warehouses w ON w.tenant_id=l.tenant_id AND w.id=l.warehouse_id WHERE l.tenant_id=? ORDER BY l.created_at DESC LIMIT 250",t));
        data.put("inspections",s.list("SELECT q.*,l.number AS lot,l.source_id,l.source_type,i.name AS item,b.quantity FROM inspections q JOIN lots l ON l.tenant_id=q.tenant_id AND l.id=q.lot_id JOIN items i ON i.tenant_id=l.tenant_id AND i.id=l.item_id JOIN stock_balances b ON b.tenant_id=l.tenant_id AND b.lot_id=l.id WHERE q.tenant_id=? ORDER BY q.created_at DESC LIMIT 250",t));
        data.put("receipts",s.list("SELECT r.*,l.number AS lot,l.status,p.number AS purchase_order FROM receipts r JOIN lots l ON l.tenant_id=r.tenant_id AND l.id=r.lot_id JOIN purchase_orders p ON p.tenant_id=r.tenant_id AND p.id=r.purchase_order_id WHERE r.tenant_id=? ORDER BY r.created_at DESC LIMIT 250",t));
        data.put("ledger",s.list("SELECT e.*,i.name AS item,l.number AS lot,w.name AS warehouse FROM stock_ledger e JOIN items i ON i.tenant_id=e.tenant_id AND i.id=e.item_id JOIN lots l ON l.tenant_id=e.tenant_id AND l.id=e.lot_id JOIN warehouses w ON w.tenant_id=e.tenant_id AND w.id=e.warehouse_id WHERE e.tenant_id=? ORDER BY e.created_at DESC,e.id LIMIT 250",t));
        data.put("mrp",s.list("WITH demand AS(SELECT om.item_id,SUM(om.required_qty) AS gross FROM order_materials om JOIN manufacturing_orders o ON o.tenant_id=om.tenant_id AND o.id=om.order_id WHERE om.tenant_id=? AND o.status IN ('DRAFT','APPROVED') GROUP BY om.item_id),stock AS(SELECT l.item_id,SUM(b.quantity-b.reserved) AS available FROM lots l JOIN stock_balances b ON b.tenant_id=l.tenant_id AND b.lot_id=l.id WHERE l.tenant_id=? AND l.status='RELEASED' GROUP BY l.item_id),incoming AS(SELECT item_id,SUM(quantity-received) AS incoming FROM purchase_orders WHERE tenant_id=? AND status IN ('APPROVED','PARTIAL') GROUP BY item_id) SELECT i.id,i.sku,i.name,i.uom,i.reorder_level,COALESCE(d.gross,0) AS gross,COALESCE(st.available,0) AS available,COALESCE(p.incoming,0) AS incoming,GREATEST(0,COALESCE(d.gross,0)+i.reorder_level-COALESCE(st.available,0)-COALESCE(p.incoming,0)) AS shortage FROM items i LEFT JOIN demand d ON d.item_id=i.id LEFT JOIN stock st ON st.item_id=i.id LEFT JOIN incoming p ON p.item_id=i.id WHERE i.tenant_id=? AND i.type<>'FINISHED_GOOD' ORDER BY shortage DESC,i.name LIMIT 250",t,t,t,t));
        data.put("trend",s.list("SELECT to_char(d,'DD Mon') AS day,COALESCE(SUM(p.good_qty),0) AS completed,COALESCE(SUM(p.scrap_qty),0) AS scrap FROM generate_series(CURRENT_DATE-(? - 1),CURRENT_DATE,interval '1 day') d LEFT JOIN production_actuals p ON p.tenant_id=? AND (p.created_at AT TIME ZONE 'Asia/Colombo')::date=d::date GROUP BY d ORDER BY d",days,t));
        data.put("metrics",s.one("SELECT (SELECT COUNT(*) FROM manufacturing_orders WHERE tenant_id=? AND status NOT IN ('CLOSED','CANCELLED','COMPLETED')) AS active_orders,(SELECT COALESCE(SUM(good_qty),0) FROM production_actuals WHERE tenant_id=? AND created_at>=CURRENT_DATE-(? - 1)) AS output,(SELECT COALESCE(SUM(scrap_qty),0) FROM production_actuals WHERE tenant_id=? AND created_at>=CURRENT_DATE-(? - 1)) AS scrap,(SELECT COUNT(*) FROM inspections WHERE tenant_id=? AND status='PENDING') AS pending_qc,(SELECT COUNT(*) FROM manufacturing_orders WHERE tenant_id=? AND due_date<CURRENT_DATE AND status NOT IN ('CLOSED','CANCELLED','COMPLETED')) AS overdue",t,t,days,t,days,t,t));
        data.put("audit",s.list("SELECT * FROM audit_events WHERE tenant_id=? ORDER BY created_at DESC,id LIMIT 100",t));
        data.put("sync",s.one("SELECT COUNT(*) AS local_events,0 AS acknowledged, 'NOT_CONFIGURED' AS status FROM outbox_events WHERE tenant_id=?",t));
        if(financial) {
            data.put("financial",s.one("SELECT (SELECT COALESCE(SUM(l.credit-l.debit),0) FROM journal_lines l JOIN journal_entries e ON e.tenant_id=l.tenant_id AND e.id=l.entry_id WHERE l.tenant_id=? AND l.account='SALES_REVENUE' AND e.created_at>=CURRENT_DATE-(? - 1)) AS revenue,(SELECT COALESCE(SUM(wip_cost),0) FROM manufacturing_orders WHERE tenant_id=?) AS wip,(SELECT COALESCE(SUM(material_cost+conversion_cost),0) FROM manufacturing_orders WHERE tenant_id=?) AS actual_cost,(SELECT COALESCE(SUM(estimated_cost),0) FROM manufacturing_orders WHERE tenant_id=? AND material_cost>0) AS estimated_cost",t,days,t,t,t));
            data.put("journal",s.list("SELECT e.reference,e.description,e.created_at,l.account,l.debit,l.credit FROM journal_entries e JOIN journal_lines l ON l.tenant_id=e.tenant_id AND l.entry_id=e.id WHERE e.tenant_id=? ORDER BY e.created_at DESC,e.id,l.debit DESC LIMIT 250",t));
        }
        return data;
    }
    Map<String,Object> details(Actor a,String id) {
        var order=s.one("SELECT o.*,i.name AS product,i.uom FROM manufacturing_orders o JOIN items i ON i.tenant_id=o.tenant_id AND i.id=o.product_id WHERE o.tenant_id=? AND o.id=?",a.tenant(),id);
        return Map.of("order",order,"materials",s.list("SELECT m.*,i.name,i.sku,i.uom FROM order_materials m JOIN items i ON i.tenant_id=m.tenant_id AND i.id=m.item_id WHERE m.tenant_id=? AND m.order_id=? ORDER BY i.name",a.tenant(),id),"actuals",s.list("SELECT * FROM production_actuals WHERE tenant_id=? AND order_id=? ORDER BY created_at",a.tenant(),id),"events",s.list("SELECT * FROM audit_events WHERE tenant_id=? AND reference=? ORDER BY created_at",a.tenant(),order.get("number")));
    }
}
